<template><main class="practice-view"><header><p>题目练习</p><h1>{{ resource?.title || '随堂练习' }}</h1><button @click="router.push('/resources')">返回资源库</button></header><section v-if="questions.length" class="practice-list"><article v-for="question in questions" :key="question.id"><p class="source" :class="question.source_level" :title="String(question.source_detail.citation || question.source_detail.source || '')">{{ sourceLabel(question) }}</p><h2>{{ question.stem }}</h2><button v-for="option in question.options" :key="option.key" :class="{ chosen: answers[question.id] === option.key }" @click="answers[question.id] = option.key">{{ option.key }}. {{ option.text }}</button><div><button class="grade" :disabled="!answers[question.id]" @click="grade(question)">查看解析</button><p v-if="grades[question.id]">{{ grades[question.id].analysis }}</p></div></article></section><p v-else class="empty">小岐正在整理这份练习。</p></main></template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { getResource } from '../services/resourceApi'
import { gradePractice } from '../services/assessmentApi'
import type { ResourceItem } from '../types/resource'
import type { AssessmentGrade, AssessmentQuestion } from '../types/assessment'
const route = useRoute(); const router = useRouter(); const resource = ref<ResourceItem>(); const answers = reactive<Record<string, string>>({}); const grades = reactive<Record<string, AssessmentGrade>>({})
const questions = computed(() => Array.isArray(resource.value?.content?.questions) ? resource.value!.content!.questions as AssessmentQuestion[] : [])
const sourceLabel = (q: AssessmentQuestion) => q.source_level === 'real' ? `真题 · ${q.source_detail.year || ''}` : q.source_level === 'adapted' ? '改编' : q.source_detail.origin === 'textbook_template' ? `教材自编 · ${q.source_detail.verified ? '已校对' : '未校对'}` : 'AI 原创'
const grade = async (q: AssessmentQuestion) => { try { grades[q.id] = await gradePractice(q.id, answers[q.id]) } catch { grades[q.id] = { question_id: q.id, correct: false, score: 0, missing_points: [], comment: '', analysis: 'Explanation is temporarily unavailable.' } } }
onMounted(async () => { resource.value = await getResource(String(route.params.id)) })
</script>
<style scoped>.practice-view{width:min(860px,100%);margin:0 auto;padding:36px 20px}.practice-view header{display:flex;gap:14px;align-items:end;border-bottom:1px solid var(--qh-border);padding-bottom:18px}.practice-view header p{margin:0;color:var(--qh-color-jade);font-size:12px}.practice-view h1{flex:1;margin:0;font-family:var(--qh-font-display)}.practice-view header button,.grade{padding:9px 13px;border:1px solid var(--qh-color-gold);border-radius:4px;color:var(--qh-primary-ink);background:var(--qh-color-gold);font-weight:800}.practice-list{display:grid;gap:14px;margin-top:24px}.practice-list article{display:grid;gap:10px;padding:22px;border:1px solid var(--qh-border);border-radius:7px;background:var(--qh-surface)}h2{margin:0;font-size:19px}.practice-list article>button{padding:11px;border:1px solid var(--qh-border);border-radius:4px;color:var(--qh-text);background:transparent;text-align:left}.practice-list article>button.chosen{border-color:var(--qh-color-jade);background:var(--qh-accent-soft)}.source{margin:0;font-size:11px}.source.real{color:var(--qh-color-gold)}.source.adapted{color:var(--qh-color-jade)}.empty{padding:50px;color:var(--qh-text-muted);text-align:center}</style>
